    context.setTransform(dpr * scale, 0, 0, dpr * scale, dpr * (cssW / 2 - (state.camera.x + shakeX) * scale), dpr * (cssH / 2 - (state.camera.y + shakeY) * scale));
    drawGround(state);
    drawSkids(state);
    drawPickups(state);
    drawMarker(state);
    const rect = visibleRect(state);
    for (const ped of state.peds) {
