    text(clockText, 20, cssH - 26, 16, PALETTE.muted, 'left');
    text(state.dusk > 0.6 ? 'Night' : state.dusk > 0.15 ? 'Dusk' : 'Day', 120, cssH - 26, 16, PALETTE.muted, 'left');
